class MainActivity:ComponentActivity(){
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContent{NSEWatcherApp(MarketViewModel(application),getSharedPreferences("nse_watcher_user",Context.MODE_PRIVATE))}}
}

class MarketViewModel(application:Application,private val repository:MarketRepository=DemoMarketRepository(application)):ViewModel(){
    private val _state=MutableStateFlow(AppState());val state:StateFlow<AppState> = _state
    init{refresh()}
    fun refresh()=viewModelScope.launch{_state.value=_state.value.copy(loading=true,error=null);repository.snapshot(true).onSuccess{s->repository.news().onSuccess{n->_state.value=AppState(s,n,false)}}.onFailure{_state.value=_state.value.copy(loading=false,error=it.message?:"Unable to load market data")}}
    fun add(symbol:String)=viewModelScope.launch{repository.addSymbol(symbol);refresh()}
    fun remove(symbol:String)=viewModelScope.launch{repository.removeSymbol(symbol);refresh()}
}

@Composable fun NSEWatcherApp(vm:MarketViewModel,prefs:SharedPreferences){
    val state by vm.state.collectAsStateWithLifecycle()
    var tab by rememberSaveable{mutableIntStateOf(0)}
    var selected by remember{mutableStateOf<Quote?>(null)}
    var settings by rememberSaveable{mutableStateOf(false)}
    var account by rememberSaveable{mutableStateOf(false)}
    var appearance by rememberSaveable{mutableStateOf(false)}
    var infoDialog by rememberSaveable{mutableStateOf<String?>(null)}
    var searchOpen by rememberSaveable{mutableStateOf(false)}
    var darkMode by rememberSaveable{mutableStateOf(prefs.getBoolean("dark_mode",false))}
    var username by rememberSaveable{mutableStateOf(prefs.getString("username","jimmymwangi")?:"jimmymwangi")}
    var email by rememberSaveable{mutableStateOf(prefs.getString("email","jimmy.mwangi@email.com")?:"jimmy.mwangi@email.com")}
    var password by rememberSaveable{mutableStateOf(prefs.getString("password","password123")?:"password123")}
    var description by rememberSaveable{mutableStateOf(prefs.getString("description","Building wealth, one stock at a time.")?:"Building wealth, one stock at a time.")}
    var avatarUri by rememberSaveable{mutableStateOf(prefs.getString("avatar_uri",null))}
    var holdings by remember{mutableStateOf(listOf(Holding("SCOM.KE",500,21.50),Holding("KCB.KE",200,38.00)))}
    var alerts by remember{mutableStateOf(listOf("SCOM.KE above KSh 30.00","KCB.KE daily gain above 5%","EABL.KE volume above average"))}
    fun savePrefs(){prefs.edit().putBoolean("dark_mode",darkMode).putString("username",username).putString("email",email).putString("password",password).putString("description",description).putString("avatar_uri",avatarUri).apply()}
    val internalBackEnabled=settings||account||appearance||selected!=null||tab!=0||searchOpen
    BackHandler(enabled=internalBackEnabled){when{searchOpen->{searchOpen=false};account->{account=false};appearance->{appearance=false};settings->{settings=false};selected!=null->{selected=null};tab!=0->{tab=0}}}
    MaterialTheme(colorScheme=if(darkMode)DarkAppColors else AppColors){Surface(Modifier.fillMaxSize(),color=MaterialTheme.colorScheme.background){when{account->AccountSettingsScreen(username,email,password,description,avatarUri,{account=false},{username=it},{email=it},{password=it},{description=it},{avatarUri=it;savePrefs()});appearance->AppearanceScreen(darkMode,{appearance=false}){darkMode=it;savePrefs()};settings->SettingsScreen(username,description,avatarUri,{settings=false},{account=true},{appearance=true},{infoDialog="Notifications will connect to alert preferences and push delivery in the live phase."},{infoDialog="Security controls will be enabled when account authentication is connected."},{infoDialog="Help and support will be connected before production release."});selected!=null->DetailScreen(selected!!){selected=null};else->MainShell(state,vm,tab,{tab=it},{selected=it},{settings=true},{searchOpen=true},holdings,{holdings=it},alerts,{alerts=it},{tab=1})};if(searchOpen)SearchDialog(state.snapshot?.quotes.orEmpty(),{searchOpen=false;selected=it},{searchOpen=false})};infoDialog?.let{msg->AlertDialog(onDismissRequest={infoDialog=null},confirmButton={TextButton(onClick={infoDialog=null}){Text("OK")}},title={Text("NSE Watcher")},text={Text(msg)})}}}
}

@Composable private fun MainShell(state:AppState,vm:MarketViewModel,tab:Int,setTab:(Int)->Unit,open:(Quote)->Unit,openSettings:()->Unit,openSearch:()->Unit,holdings:List<Holding>,setHoldings:(List<Holding>)->Unit,alerts:List<String>,setAlerts:(List<String>)->Unit,viewAllWatchlist:()->Unit){
    Scaffold(topBar={TopBar(openSettings,openSearch)},bottomBar={NavigationBar(containerColor=MaterialTheme.colorScheme.surface){val nav=listOf("Home" to Icons.Default.Home,"Watchlist" to Icons.Default.Star,"Portfolio" to Icons.Default.AccountBalanceWallet,"Alerts" to Icons.Default.Notifications,"News" to Icons.Default.Article);nav.forEachIndexed{i,item->NavigationBarItem(selected=tab==i,onClick={setTab(i)},icon={Icon(item.second,item.first,modifier=Modifier.size(24.dp))},label={Text(item.first)},colors=NavigationBarItemDefaults.colors(selectedIconColor=Green,selectedTextColor=Green,indicatorColor=LightGreen,unselectedIconColor=Muted,unselectedTextColor=Muted))}}}){padding->Box(Modifier.fillMaxSize().padding(padding)){when{state.loading->CircularProgressIndicator(Modifier.align(Alignment.Center),color=Green);state.error!=null&&state.snapshot==null->ErrorState(state.error!!,vm::refresh);tab==0->Dashboard(state,open,viewAllWatchlist);tab==1->Watchlist(state.snapshot?.quotes.orEmpty(),vm::add,vm::remove,open);tab==2->PortfolioScreen(holdings,setHoldings);tab==3->AlertsScreen(alerts,setAlerts);else->NewsScreen(state.news)}}}}

