@Composable private fun Dashboard(state:AppState,open:(Quote)->Unit,viewAll:()->Unit){
    val quotes=state.snapshot?.quotes.orEmpty();val gainers=quotes.sortedByDescending{it.dailyChange};val losers=quotes.sortedBy{it.dailyChange}
    LazyColumn(contentPadding=PaddingValues(start=16.dp,end=16.dp,top=8.dp,bottom=18.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        item{MarketHero(state.snapshot?.updatedAt?.toString()?.take(16)?:"—")}
        item{MarketSummary(quotes)}
        item{SectionTitle("Market Indices","NSE benchmark snapshot")};item{IndicesRow()}
        item{SectionTitleWithAction("🔥 Market Movers","Top gainers and losers","View All",{})};item{MarketMovers(gainers.take(4),losers.take(4),open)}
        item{SectionTitleWithAction("⭐ Your Watchlist","Your tracked stocks","View All",viewAll)};item{LazyRow(contentPadding=PaddingValues(horizontal=1.dp),horizontalArrangement=Arrangement.spacedBy(10.dp)){items(quotes.take(6),key={it.symbol}){q->HorizontalStockCard(q){open(q)}}}}
        item{SectionTitle("🧠 NSE Watcher Intelligence","Explainable demo analysis")};item{IntelligenceSummary(quotes)}
        item{SectionTitleWithAction("📰 Latest News","From your tracked stocks","View All",{})};items(state.news.take(3),key={it.id}){NewsCard(it)}
        item{DemoBanner()}
    }
}

