@Composable private fun Sparkline(values:List<Double>,modifier:Modifier,tint:Color){Canvas(modifier){if(values.size>1){val min=values.minOrNull()?:0.0;val max=values.maxOrNull()?:1.0;val range=(max-min).takeIf{it>0}?:1.0;val path=Path();values.forEachIndexed{i,v->val x=size.width*i/values.lastIndex;val y=size.height-((v-min)/range).toFloat()*size.height;if(i==0)path.moveTo(x,y)else path.lineTo(x,y)};drawPath(path,tint,style=androidx.compose.ui.graphics.drawscope.Stroke(width=3.5f))}}}

