oundedCornerShape(16.dp),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.surfaceVariant)){Column(Modifier.padding(13.dp)){Text("About this analysis",fontWeight=FontWeight.Bold);Text("NSE Watcher is an information and analysis tool. Scores and sample metrics are not investment advice, price predictions, or guarantees.",color=Muted,style=MaterialTheme.typography.bodySmall)}}}}

