@Composable private fun PortfolioScreen(holdings:List<Holding>,update:(List<Holding>)->Unit){val prices=mapOf("SCOM.KE" to 18.65,"KCB.KE" to 39.85,"EQTY.KE" to 47.20,"ABSA.KE" to 13.40,"COOP.KE" to 15.80,"EABL.KE" to 38.60);val invested=holdings.sumOf{it.shares*it.averagePrice};val current=holdings.sumOf{it.shares*(prices[it.symbol]?:it.averagePrice)};val pnl=current-invested;LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Card(shape=RoundedCornerShape(20.dp),colors=CardDefaults.cardColors(containerColor=LightGreen)){Column(Modifier.padding(17.dp)){Text("Portfolio Value",color=Muted);Text("KSh %,.2f".format(current),style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.ExtraBold);Text("%+.2f  (%+.1f%%)".format(pnl,if(invested==0.0)0.0 else pnl/invested*100),color=if(pnl>=0)Green else Red,fontWeight=FontWeight.Bold)}}};item{Text("Holdings",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.ExtraBold)};items(holdings,key={it.symbol}){h->val price=prices[h.symbol]?:h.averagePrice;val value=h.shares*price;val gain=value-h.shares*h.averagePrice;Card(shape=RoundedCornerShape(17.dp),border=BorderStroke(1.dp,BorderGreen),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.surface)){Row(Modifier.fillMaxWidth().padding(14.dp),horizontalArrangement=Arrangement.SpaceBetween){Column{Text(h.symbol,fontWeight=FontWeight.ExtraBold);Text("${h.shares} shares • Avg KSh %.2f".format(h.averagePrice),color=Muted,style=MaterialTheme.typography.bodySmall)};Column(horizontalAlignment=Alignment.End){Text("KSh %,.2f".format(value),fontWeight=FontWeight.ExtraBold);Text("%+.2f".format(gain),color=if(gain>=0)Green else Red,fontWeight=FontWeight.Bold)}}}};item{Button(onClick={update(holdings+Holding("EQTY.KE",100,45.00))},Modifier.fillMaxWidth()){Icon(Icons.Default.Add,null);Spacer(Modifier.width(5.dp));Text("Add demo holding")}};item{Text("Portfolio values are demo calculations for now.",color=Muted,style=MaterialTheme.typography.bodySmall)}}}

