private fun fmt(value:Double):String=when{value>=1_000_000_000->"%.1fB".format(value/1_000_000_000);value>=1_000_000->"%.1fM".format(value/1_000_000);value>=1_000->"%.1fK".format(value/1_000);else->"%.0f".format(value)}
